(() => {

  const r =
    $('Consenso Editorial v0.1.0').first().json ?? {};

  const d =
    r.duplicidade_editorial ?? {};

  const ce =
    r.consenso_editorial ?? {};

  const c =
    r.candidato ?? {};

  const m =
    d.melhor_match ?? {};

  const metricas =
    m.metricas ?? {};

  const top =
    Array.isArray(d.top_matches)
      ? d.top_matches
      : [];

  const limites =
    d.limites ?? {};

  const sinais =
    ce.sinais ?? {};

  const consenso =
    ce.consenso ?? {};


  // ==========================================================
  // HELPERS
  // ==========================================================

  const esc = (value) =>
    String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');


  const valor = (value, fallback = '-') =>
    value === null ||
    value === undefined ||
    value === ''
      ? fallback
      : esc(value);


  const simNao = (value) =>
    value
      ? 'SIM'
      : 'NÃO';


  const listaTokens =
    Array.isArray(metricas.lista_tokens_comuns)
      ? metricas.lista_tokens_comuns.join(', ')
      : '-';


  const tokensCandidato =
    Array.isArray(d.candidato?.tokens)
      ? d.candidato.tokens.join(', ')
      : '-';


  const tokensFracos =
    Array.isArray(
      d.candidato?.tokens_editoriais_fracos_ignorados
    )
      ? (
          d.candidato.tokens_editoriais_fracos_ignorados.length
            ? d.candidato.tokens_editoriais_fracos_ignorados.join(', ')
            : 'Nenhum'
        )
      : 'Nenhum';


  const fontesTop3 =
    Array.isArray(
      consenso.fontes_distintas_top3
    )
      ? consenso.fontes_distintas_top3.join(', ')
      : '-';


  // ==========================================================
  // TOP 3
  // ==========================================================

  const topHtml =
    top.length
      ? top.map((match, index) => {

          const mm =
            match.metricas ?? {};

          const tokens =
            Array.isArray(mm.lista_tokens_comuns)
              ? mm.lista_tokens_comuns.join(', ')
              : '-';

          return `
            <tr>

              <td style="
                padding:8px;
                border:1px solid #ddd;
                text-align:center;
              ">
                ${index + 1}
              </td>

              <td style="
                padding:8px;
                border:1px solid #ddd;
              ">

                <strong>
                  ${valor(match.titulo)}
                </strong>

                <br>

                <small>
                  ID: ${valor(match.id)}
                  |
                  Categoria: ${valor(match.categoria)}
                </small>

              </td>

              <td style="
                padding:8px;
                border:1px solid #ddd;
              ">
                ${valor(match.origem)}
              </td>

              <td style="
                padding:8px;
                border:1px solid #ddd;
                text-align:center;
              ">

                <strong>
                  ${valor(mm.percentual, 0)}%
                </strong>

              </td>

              <td style="
                padding:8px;
                border:1px solid #ddd;
                text-align:center;
              ">
                ${valor(mm.tokens_comuns, 0)}
              </td>

              <td style="
                padding:8px;
                border:1px solid #ddd;
              ">
                ${esc(tokens)}
              </td>

            </tr>
          `;

        }).join('')
      : `
          <tr>
            <td
              colspan="6"
              style="
                padding:10px;
                border:1px solid #ddd;
              "
            >
              Nenhum match disponível.
            </td>
          </tr>
        `;


  // ==========================================================
  // SAÍDA HTML
  // ==========================================================

  return `

<div style="
  font-family:Arial,Helvetica,sans-serif;
  color:#222;
  line-height:1.5;
  max-width:1000px;
  margin:0 auto;
">

