return [
  {
    json: {

      ...origem,

      consenso_editorial: {

        versao:
          CONFIG.versao,

        modo:
          CONFIG.modo,

        aplicado_automaticamente:
          false,

        altera_status_core:
          false,

        status_original:
          duplicidade.status ?? null,

        status_sugerido:
          statusSugerido,

        nivel:
          nivelConsenso,

        motivo,

        resumo,


        // ------------------------------------------------------
        // TOP 1
        // ------------------------------------------------------

        top1: {

          id:
            top1?.id ?? null,

          titulo:
            top1?.titulo ?? null,

          origem:
            origemTop1,

          score:
            scoreTop1,

          percentual:
            percentualTop1,

          tokens_comuns:
            tokensTop1,

          cobertura:
            coberturaTop1,

          cobertura_percentual:
            percentual(
              coberturaTop1
            )

        },


        // ------------------------------------------------------
        // TOP 2
        // ------------------------------------------------------

        top2: {

          id:
            top2?.id ?? null,

          titulo:
            top2?.titulo ?? null,

          origem:
            origemTop2,

          score:
            scoreTop2,

          percentual:
            percentualTop2,

          tokens_comuns:
            tokensTop2,

          cobertura:
            coberturaTop2,

          cobertura_percentual:
            percentual(
              coberturaTop2
            )

        },


        // ------------------------------------------------------
        // TOP 3
        // ------------------------------------------------------

        top3: {

          id:
            top3?.id ?? null,

          titulo:
            top3?.titulo ?? null,

          origem:
            origemTop3,

          score:
            scoreTop3,

          percentual:
            percentualTop3,

          tokens_comuns:
            tokensTop3,

          cobertura:
            coberturaTop3,

          cobertura_percentual:
            percentual(
              coberturaTop3
            )

        },


        // ------------------------------------------------------
        // CONSENSO
        // ------------------------------------------------------

        consenso: {

          multifonte:
            totalFontesDistintas >= 2,

          fontes_top1_top2_distintas:
            top1Top2FontesDistintas,

          total_fontes_distintas_top3:
            totalFontesDistintas,

          fontes_distintas_top3:
            fontesDistintas,

          gap_top1_top2:
            Number(
              gapTop1Top2.toFixed(4)
            ),

          percentual_gap_top1_top2:
            percentualGapTop1Top2

        },


        // ------------------------------------------------------
        // SINAIS
        // ------------------------------------------------------

        sinais,


        // ------------------------------------------------------
        // REGRAS AUDITADAS
        // ------------------------------------------------------

        regras: {

          consenso_forte: {

            atingido:
              regraForte,

            score_top1_min:
              CONFIG.consensoForte.scoreTop1Min,

            score_top2_min:
