            tokens_top1_min:
              CONFIG.consensoForte.tokensTop1Min,

            cobertura_top1_min:
              CONFIG.consensoForte.coberturaTop1Min,

            exigir_fontes_distintas:
              CONFIG.consensoForte.exigirFontesDistintas

          },

